    votes: Seq<(u64, u64, u64)>, view: u64, seq_num: u64, threshold: u64,
) -> bool {
    vote_count_spec(votes, view, seq_num) >= threshold as int
}

// r[impl quorum-cert.is-valid-qc]
/// Check if enough votes form a valid quorum certificate.
pub fn is_valid_qc(
